-- Retrospective final IEX archive context, not original consumer-availability or factor attribution.
-- Run through existing read-only ClickHouse account; no combined SIP data.
SELECT toDate(event_at,'America/New_York') AS session_date,count() AS retained_minutes,min(event_at) AS first_bar,max(event_at) AS last_bar,argMin(b.1,event_at) AS first_open,argMax(b.4,event_at) AS last_close,(argMax(b.4,event_at)/argMin(b.1,event_at)-1)*10000 AS regular_return_bps FROM (SELECT coalesce(event_ts_exact,toDateTime64(event_ts,9,'UTC')) AS event_at,argMax(tuple(open,high,low,close),tuple(coalesce(ingest_ts_exact,toDateTime64(ingest_ts,9,'UTC')),source_topic,source_partition,source_offset,universe_id,universe_symbol_hash,channel,tuple(open,high,low,close))) AS b FROM signal.intraday_bars_1m_v2 WHERE symbol='SPY' AND event_ts>='2026-11-16 00:00:00' AND event_ts<'2026-11-26 00:00:00' AND ingest_ts<'2026-11-26 08:40:00' AND provider='alpaca' AND feed='iex' AND is_final=1 AND channel IN ('bars','updatedBars') AND formatDateTime(event_ts,'%H:%i','America/New_York')>='09:30' AND formatDateTime(event_ts,'%H:%i','America/New_York')<'16:00' GROUP BY event_at) GROUP BY session_date ORDER BY session_date FORMAT JSONEachRow;
